function estimateOps(n, complexity) {
  const ops = {
    'O(log n)': Math.ceil(Math.log2(n)),
    'O(n)': n,
    'O(n log n)': Math.ceil(n * Math.log2(n)),
    'O(n²)': n * n,
    'O(n³)': n * n * n,
    'O(2^n)': Math.pow(2, n)
  };
  return ops[complexity] || 0;
}
const budget = 1e8;
function fastest(n) {
  const order = ['O(2^n)', 'O(n³)', 'O(n²)', 'O(n log n)', 'O(n)', 'O(log n)'];
  for (const c of order) {
    if (estimateOps(n, c) <= budget) return c;
  }
  return 'O(log n)';
}
for (const n of [10, 500, 5000, 1000000]) {
  console.log('n <= ' + n + ' -> slowest tolerable: ' + fastest(n));
}
console.log('n=1e6 O(n²) ops = ' + estimateOps(1000000, 'O(n²)') + ' (budget ' + budget + ')');
